import SwiftRuleEngine

let rules: [[String: Any]] = [[
    "name": "volume-discount",
    "conditions": ["all": [
        ["path": "$.units", "operator": "greater_than", "value": 100],
        ["path": "$.loyaltyYears", "operator": "greater_than", "value": 2]
    ]]
]]

let engine = try RuleEngine(rules: rules, customOperators: [])

let bulkOrder = NSCompoundPredicate(andPredicateWithSubpredicates: [
    NSPredicate(format: "units > %d", 100),
    NSPredicate(format: "loyaltyYears > %d", 2)
])

if bulkOrder.evaluate(with: order) {
    order.discount = 0.10
}

